import{_ as t,o as i,c as a,ae as s}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"ADR-0002: Testing Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0002-testing-strategy.md","filePath":"adr/ADR-0002-testing-strategy.md"}'),o={name:"adr/ADR-0002-testing-strategy.md"};function n(r,e,l,c,d,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0002-testing-strategy" tabindex="-1">ADR-0002: Testing Strategy <a class="header-anchor" href="#adr-0002-testing-strategy" aria-label="Permalink to &quot;ADR-0002: Testing Strategy&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-07-09<br><strong>Deciders:</strong> HeliosBench Maintainers</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>HeliosBench needs a testing strategy that ensures correctness of benchmark results, reliability of resource monitoring, and maintainability as the codebase grows. The tool processes numeric data from system monitoring, serializes complex nested dataclasses, and must handle edge cases in task execution.</p><p>Testing concerns:</p><ol><li>Correctness of statistical calculations (trend analysis, aggregation)</li><li>Handling of edge cases in resource monitoring (empty samples, missing data)</li><li>Serialization/deserialization of benchmark results</li><li>Task configuration validation</li><li>Regression detection across code changes</li></ol><hr><h2 id="decision-1-layered-testing-approach" tabindex="-1">Decision 1: Layered Testing Approach <a class="header-anchor" href="#decision-1-layered-testing-approach" aria-label="Permalink to &quot;Decision 1: Layered Testing Approach&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Use a three-layer testing strategy:</p><ol><li><strong>Unit tests</strong> (<code>tests/test_benchmark.py</code>): Test individual functions and classes with mocked dependencies</li><li><strong>Property-based tests</strong> (<code>tests/test_property_based.py</code>): Verify invariants across randomly generated inputs using Hypothesis</li><li><strong>Future: Integration tests</strong>: End-to-end tests with a mock binary</li></ol><h3 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>Unit tests provide fast, targeted verification of business logic</li><li>Property-based tests catch edge cases that example-based tests miss (empty lists, extreme values, NaN, zero divisions)</li><li>Integration tests validate the full pipeline but are slower and environment-dependent</li></ul><h3 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Comprehensive coverage across all testing layers</li><li>Positive: Property-based tests generate diverse inputs automatically</li><li>Positive: Mock-based unit tests run quickly in CI</li><li>Negative: Property-based tests have non-deterministic execution time</li><li>Negative: Integration tests require a test binary and are not yet implemented</li></ul><hr><h2 id="decision-2-property-based-testing-for-data-processing-code" tabindex="-1">Decision 2: Property-Based Testing for Data-Processing Code <a class="header-anchor" href="#decision-2-property-based-testing-for-data-processing-code" aria-label="Permalink to &quot;Decision 2: Property-Based Testing for Data-Processing Code&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-1" tabindex="-1">Decision <a class="header-anchor" href="#decision-1" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Use the <code>hypothesis</code> library for property-based testing of:</p><ul><li><code>ResourceMonitor.aggregate()</code> — invariant checks on statistical outputs</li><li><code>LeakDetector._calc_trend()</code> — correctness of linear regression trend calculation</li><li><code>BenchmarkTask</code> — validation of task configuration invariants</li><li>Result serialization — round-trip equality for JSON/YAML</li><li><code>_compare_results()</code> — comparison metric invariants</li></ul><h3 id="rationale-1" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-1" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>Resource monitoring and comparison logic are data-processing functions with clear mathematical invariants</li><li>Hypothesis generates edge cases (empty lists, NaN, extreme values) that manual tests often miss</li><li>Property-based tests serve as executable specifications for mathematical properties</li></ul><h3 id="consequences-1" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-1" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Finds edge-case bugs in statistical calculations automatically</li><li>Positive: Tests document mathematical invariants (e.g., max &gt;= mean always)</li><li>Positive: Hypothesis shrinks failing cases to minimal reproducers</li><li>Negative: Tests take longer to run than example-based tests</li><li>Negative: Floating-point comparisons require tolerances (unlikely/approx)</li></ul><hr><h2 id="decision-3-coverage-threshold-with-enforcement" tabindex="-1">Decision 3: Coverage Threshold with Enforcement <a class="header-anchor" href="#decision-3-coverage-threshold-with-enforcement" aria-label="Permalink to &quot;Decision 3: Coverage Threshold with Enforcement&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-2" tabindex="-1">Decision <a class="header-anchor" href="#decision-2" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Maintain a minimum line coverage threshold of 70%, enforced via <code>pytest-cov</code> with <code>--cov-fail-under=70</code>. Coverage is measured for the <code>src/</code> package, excluding <code>__init__.py</code> entry points.</p><h3 id="rationale-2" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-2" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>70% is a realistic initial target for a codebase at this stage</li><li>Coverage enforcement prevents untested code from being merged</li><li>The threshold can increase to 80% as the test suite matures</li></ul><h3 id="consequences-2" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-2" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Ensures minimum quality bar for all contributions</li><li>Positive: Coverage reports visible in CI output</li><li>Negative: Coverage is a proxy metric — 70% coverage doesn&#39;t guarantee 70% of behaviors tested</li><li>Negative: Some error-handling branches are difficult to trigger in tests</li></ul><hr><h2 id="decision-4-mock-based-testing-for-system-dependent-code" tabindex="-1">Decision 4: Mock-Based Testing for System-Dependent Code <a class="header-anchor" href="#decision-4-mock-based-testing-for-system-dependent-code" aria-label="Permalink to &quot;Decision 4: Mock-Based Testing for System-Dependent Code&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-3" tabindex="-1">Decision <a class="header-anchor" href="#decision-3" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Use <code>unittest.mock</code> to isolate tests from system-dependent behavior:</p><ul><li><code>psutil.Process</code> calls are mocked in resource monitoring tests</li><li><code>subprocess.Popen</code> is mocked in benchmark runner tests</li><li><code>threading.Thread</code> is mocked to avoid actual thread creation in tests</li></ul><h3 id="rationale-3" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-3" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>System monitoring code depends on OS process state that doesn&#39;t exist in CI</li><li>Mocking allows testing of logic (aggregation, trend analysis) without external dependencies</li><li>Mocked tests are deterministic and fast</li></ul><h3 id="consequences-3" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-3" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Tests run on any platform without system dependencies</li><li>Positive: Fast test execution enables rapid iteration</li><li>Negative: Tests may diverge from real system behavior if mocks are inaccurate</li><li>Negative: Requires discipline to keep mocks in sync with real APIs</li></ul><hr><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>All four decisions are accepted and reflected in the current test suite and CI configuration.</p>',49)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
